import{a as e,c as t,d as n,i as r,o as i,r as a,s as o,t as s,u as c}from"./app-D6FlNkEn.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/tutorial/more-about-jobs.html","title":"More About Jobs & JobDetails","lang":"en-US","frontmatter":{"title":"More About Jobs & JobDetails"},"git":{"updatedTime":1787413150000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"99c1c648b015bd52dedc833fab86ff9aa7316a5f","time":1787413150000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"Give the schema-changes page anchors VuePress actually emits","coAuthors":[{"name":"Claude Fable 5","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/tutorial/more-about-jobs.md"}`),u={name:`more-about-jobs.md`},d={class:`hint-container tip`};function f(s,l,u,f,p,m){let h=c(`RouteLink`);return t(),r(`div`,null,[l[12]||=e(`<p>As you saw in Lesson 2, jobs are rather easy to implement. There are just a few more things that you need to understand about the nature of jobs, about the <code>Execute(..)</code> method of the <code>IJob</code> interface, and about JobDetails.</p><p>While a job class that you implement has the code that knows how to do the actual work of the particular type of job, Quartz.NET needs to be informed about various attributes that you may wish an instance of that job to have. This is done via the JobDetail class, which was mentioned briefly in the previous section.</p><p>JobDetail instances are built using the <code>JobBuilder</code> class. <code>JobBuilder</code> allows you to describe your job&#39;s details using a fluent interface.</p><p>Let&#39;s take a moment now to discuss a bit about the &#39;nature&#39; of jobs and the life-cycle of job instances within Quartz.NET. First lets take a look back at some of that snippet of code we saw in Lesson 1:</p><p><strong>Using Quartz.NET</strong></p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// define the job and tie it to our HelloJob class</span></span>
<span class="line"><span class="token class-name">IJobDetail</span> job <span class="token operator">=</span> JobBuilder<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Create</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>HelloJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myJob&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;group1&quot;</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Trigger the job to run now, and then every 40 seconds</span></span>
<span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myTrigger&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;group1&quot;</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">StartNow</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">WithSimpleSchedule</span><span class="token punctuation">(</span>x <span class="token operator">=&gt;</span> x</span>
<span class="line">   <span class="token punctuation">.</span><span class="token function">WithInterval</span><span class="token punctuation">(</span>TimeSpan<span class="token punctuation">.</span><span class="token function">FromSeconds</span><span class="token punctuation">(</span><span class="token number">40</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">   <span class="token punctuation">.</span><span class="token function">RepeatForever</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line"><span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">ScheduleJob</span><span class="token punctuation">(</span>job<span class="token punctuation">,</span> trigger<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Now consider the job class <strong>HelloJob</strong> defined as such:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">HelloJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">await</span> Console<span class="token punctuation">.</span>Out<span class="token punctuation">.</span><span class="token function">WriteLineAsync</span><span class="token punctuation">(</span><span class="token string">&quot;HelloJob is executing.&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Notice that we give the scheduler a <code>IJobDetail</code> instance, and that it refers to the job to be executed by simply providing the job&#39;s class. Each (and every) time the scheduler executes the job, it creates a new instance of the class before calling its <code>Execute(..)</code> method. Under <code>AddQuartz</code> that instance comes from the service container, inside a scope of its own, so the job can take its dependencies through its constructor the way the rest of your application does. A ramification that does still hold is that it makes no sense to keep state in fields on the job class — the instance is gone when the fire ends, so nothing in it is preserved between executions.</p><p>You may now be wanting to ask &quot;how can I provide properties/configuration for a Job instance?&quot; and &quot;how can I keep track of a job&#39;s state between executions?&quot; The answer to these questions are the same: the key is the <code>JobDataMap</code>, which is part of the JobDetail object.</p><h2 id="jobdatamap" tabindex="-1"><a class="header-anchor" href="#jobdatamap"><span>JobDataMap</span></a></h2><p>The <code>JobDataMap</code> can be used to hold any number of (serializable) objects which you wish to have made available to the job instance when it executes. <code>JobDataMap</code> implements <code>IDictionary&lt;string, object?&gt;</code>, and a set of typed accessors — <code>GetString</code>, <code>GetInt</code>, <code>GetDateTimeOffset</code>, <code>GetEnum&lt;T&gt;</code>, <code>TryGet&lt;T&gt;</code> and the rest — come with it as extension methods, so <code>map.GetString(&quot;key&quot;)</code> works on any map without a cast or a lookup of your own.</p>`,12),a(`p`,null,[l[1]||=i(`This section is the introduction. `,-1),o(h,{to:`/documentation/quartz-4.x/tutorial/job-data-map.html`},{default:n(()=>[...l[0]||=[i(`Job Data`,-1)]]),_:1}),l[2]||=i(` has the full inventory: every accessor, the `,-1),l[3]||=a(`code`,null,`PutAsString`,-1),l[4]||=i(` round-trip formats, the merge rules, how string-mode storage changes what you may put in the map, and what does not belong in job data at all.`,-1)]),l[13]||=e(`<p>Here&#39;s some quick snippets of putting data into the JobDataMap prior to adding the job to the scheduler:</p><p><strong>Setting Values in a JobDataMap</strong></p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token comment">// define the job and tie it to our DumbJob class</span></span>
<span class="line"><span class="token class-name">IJobDetail</span> job <span class="token operator">=</span> JobBuilder<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Create</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DumbJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myJob&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;group1&quot;</span><span class="token punctuation">)</span> <span class="token comment">// name &quot;myJob&quot;, group &quot;group1&quot;</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span><span class="token string">&quot;jobSays&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Hello World!&quot;</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span><span class="token string">&quot;myFloatValue&quot;</span><span class="token punctuation">,</span> <span class="token number">3.141f</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Here&#39;s a quick example of getting data from the JobDataMap during the job&#39;s execution:</p><p><strong>Getting Values from a JobDataMap</strong></p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DumbJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token class-name">JobKey</span> key <span class="token operator">=</span> context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token class-name">JobDataMap</span> dataMap <span class="token operator">=</span> context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>JobDataMap<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token class-name"><span class="token keyword">string</span></span> jobSays <span class="token operator">=</span> dataMap<span class="token punctuation">.</span><span class="token function">GetString</span><span class="token punctuation">(</span><span class="token string">&quot;jobSays&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token class-name"><span class="token keyword">float</span></span> myFloatValue <span class="token operator">=</span> dataMap<span class="token punctuation">.</span><span class="token function">GetFloat</span><span class="token punctuation">(</span><span class="token string">&quot;myFloatValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">await</span> Console<span class="token punctuation">.</span>Error<span class="token punctuation">.</span><span class="token function">WriteLineAsync</span><span class="token punctuation">(</span><span class="token string">&quot;Instance &quot;</span> <span class="token operator">+</span> key <span class="token operator">+</span> <span class="token string">&quot; of DumbJob says: &quot;</span> <span class="token operator">+</span> jobSays <span class="token operator">+</span> <span class="token string">&quot;, and val is: &quot;</span> <span class="token operator">+</span> myFloatValue<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>If you use a persistent JobStore (discussed in the JobStore section of this tutorial) you should use some care in deciding what you place in the JobDataMap, because the object in it will be serialized, and they therefore become prone to class-versioning problems. Obviously standard .NET types should be very safe, but beyond that, any time someone changes the definition of a class for which you have serialized instances, care has to be taken not to break compatibility.</p><p>Optionally, you can put AdoJobStore and JobDataMap into a mode where only primitives and strings can be stored in the map, thus eliminating any possibility of later serialization problems.</p><p>If you add properties with set accessor to your job class that correspond to the names of keys in the JobDataMap, then Quartz&#39;s default JobFactory implementation will automatically call those setters when the job is instantiated, thus preventing the need to explicitly get the values out of the map within your execute method. Note this functionality is not maintained by default when using a custom JobFactory.</p><h3 id="naming-the-property-instead-of-the-key" tabindex="-1"><a class="header-anchor" href="#naming-the-property-instead-of-the-key"><span>Naming the property instead of the key</span></a></h3><p>When the value is meant for one of those properties, you can name the property rather than spell its key. The key is then the property&#39;s own name, and the value has to be of the property&#39;s own type:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DumbJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> JobSays <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> FloatValue <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"> <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">IJobDetail</span> job <span class="token operator">=</span> JobBuilder<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Create</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DumbJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myJob&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;group1&quot;</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span>JobSays<span class="token punctuation">,</span> <span class="token string">&quot;Hello World!&quot;</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span>FloatValue<span class="token punctuation">,</span> <span class="token number">3.141f</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>JobBuilder.Create&lt;DumbJob&gt;()</code> returns a <code>JobBuilder&lt;DumbJob&gt;</code>, and it is that job type which lets <code>j</code> be inferred. <code>JobBuilder.Create()</code> builds for <code>IJob</code>, which has no properties to name, so use the generic overload when you want to configure a job this way. Nothing is instantiated - the expression is only read, never run.</p><p>The property has to be readable as well as publicly settable for this to work, so a property declared <code>{ private get; set; }</code> cannot be named this way. Give it an ordinary getter if you want to configure it by name.</p><p>A mistake is caught rather than swallowed. A property of an unrelated job does not compile at all, and everything the compiler cannot rule out is rejected on the spot: a property with no public setter, a nested path such as <code>j =&gt; j.Something.Nested</code>, a property reached by casting the job to another type, a value that will not convert to the property&#39;s type or would lose information doing so, and a <code>null</code> for a property that cannot hold one. Compare that to a mistyped string key, which binds to nothing and leaves the job running with its defaults, or a wrong-typed value, which is silently coerced.</p><p>The remaining rules all follow from one thing: only a <em>name</em> reaches the map, and the job factory turns that name back into a property by its own lookup. So the check is simply to run that lookup and insist it arrives back at the property you named. A property whose name starts with a lower-case letter fails it, because keys are only ever looked up with the first character upper-cased; so does one that implements an interface explicitly, because it is not public on the job class; and so does one whose name resolves to a different property of another type, which is what a <code>new</code> member hiding a base property does.</p><p>An enum is stored as its name, so it survives a persistent store and still reads sensibly in the map itself. Otherwise the same care applies as to any other job data: the store has to be able to serialize the value.</p><p>Triggers work the same way through <code>TriggerBuilder.Create&lt;DumbJob&gt;()</code>, which is how one job takes different inputs per trigger:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">ITrigger</span> trigger <span class="token operator">=</span> TriggerBuilder<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Create</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DumbJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myTrigger&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;group1&quot;</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">ForJob</span><span class="token punctuation">(</span>job<span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span>JobSays<span class="token punctuation">,</span> <span class="token string">&quot;Good evening!&quot;</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>ForJob(IJobDetail)</code> also checks that the job really is a <code>DumbJob</code>, since that is the one overload that knows the job&#39;s type.</p>`,20),a(`p`,null,[l[6]||=i(`The same applies to the configurators in the `,-1),o(h,{to:`/documentation/quartz-4.x/packages/microsoft-di-integration.html`},{default:n(()=>[...l[5]||=[i(`Microsoft DI integration`,-1)]]),_:1}),l[7]||=i(`, where the job type comes from the call itself:`,-1)]),l[14]||=e(`<div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DumbJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span>x <span class="token operator">=&gt;</span> x<span class="token punctuation">.</span>JobSays<span class="token punctuation">,</span> <span class="token string">&quot;Hello World!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">ScheduleJob</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DumbJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span></span>
<span class="line"> t <span class="token operator">=&gt;</span> t<span class="token punctuation">.</span><span class="token function">StartNow</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span>x <span class="token operator">=&gt;</span> x<span class="token punctuation">.</span>JobSays<span class="token punctuation">,</span> <span class="token string">&quot;Good evening!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"> j <span class="token operator">=&gt;</span> j<span class="token punctuation">.</span><span class="token function">WithIdentity</span><span class="token punctuation">(</span><span class="token string">&quot;myJob&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// a trigger added on its own names the job type it fires</span></span>
<span class="line">q<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">AddTrigger</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>DumbJob<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>t <span class="token operator">=&gt;</span> t<span class="token punctuation">.</span><span class="token function">ForJob</span><span class="token punctuation">(</span>jobKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">UsingJobData</span><span class="token punctuation">(</span>x <span class="token operator">=&gt;</span> x<span class="token punctuation">.</span>JobSays<span class="token punctuation">,</span> <span class="token string">&quot;Good evening!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>AddTrigger&lt;IJob&gt;</code> is the untyped form — <code>IJob</code> has no properties to name — so name the job&#39;s own type when you want typed trigger data.</p><p>Triggers can also have JobDataMaps associated with them. This can be useful in the case where you have a Job that is stored in the scheduler for regular/repeated use by multiple Triggers, yet with each independent triggering, you want to supply the Job with different data inputs.</p><p>The JobDataMap that is found on the JobExecutionContext during Job execution serves as a convenience. It is a merge of the JobDataMap found on the JobDetail and the one found on the Trigger, with the values in the latter overriding any same-named values in the former.</p><p>Here&#39;s a quick example of getting data from the JobExecutionContext&#39;s merged JobDataMap during the job&#39;s execution:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DumbJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token class-name">JobKey</span> key <span class="token operator">=</span> context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token class-name">JobDataMap</span> dataMap <span class="token operator">=</span> context<span class="token punctuation">.</span>MergedJobDataMap<span class="token punctuation">;</span>  <span class="token comment">// Note the difference from the previous example</span></span>
<span class="line"></span>
<span class="line">  <span class="token class-name"><span class="token keyword">string</span></span> jobSays <span class="token operator">=</span> dataMap<span class="token punctuation">.</span><span class="token function">GetString</span><span class="token punctuation">(</span><span class="token string">&quot;jobSays&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token class-name"><span class="token keyword">float</span></span> myFloatValue <span class="token operator">=</span> dataMap<span class="token punctuation">.</span><span class="token function">GetFloat</span><span class="token punctuation">(</span><span class="token string">&quot;myFloatValue&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token class-name">IList<span class="token punctuation">&lt;</span>DateTimeOffset<span class="token punctuation">&gt;</span></span> state <span class="token operator">=</span> <span class="token punctuation">(</span>IList<span class="token operator">&lt;</span>DateTimeOffset<span class="token operator">&gt;</span><span class="token punctuation">)</span>dataMap<span class="token punctuation">[</span><span class="token string">&quot;myStateData&quot;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  state<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>DateTimeOffset<span class="token punctuation">.</span>UtcNow<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">await</span> Console<span class="token punctuation">.</span>Error<span class="token punctuation">.</span><span class="token function">WriteLineAsync</span><span class="token punctuation">(</span><span class="token string">&quot;Instance &quot;</span> <span class="token operator">+</span> key <span class="token operator">+</span> <span class="token string">&quot; of DumbJob says: &quot;</span> <span class="token operator">+</span> jobSays <span class="token operator">+</span> <span class="token string">&quot;, and val is: &quot;</span> <span class="token operator">+</span> myFloatValue<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Or if you wish to rely on the JobFactory &quot;injecting&quot; the data map values onto your class, it might look like this instead:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DumbJob</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJob</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> JobSays <span class="token punctuation">{</span> <span class="token keyword">private</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"> <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> FloatValue <span class="token punctuation">{</span> <span class="token keyword">private</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"> <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">ValueTask</span> <span class="token function">Execute</span><span class="token punctuation">(</span><span class="token class-name">IJobExecutionContext</span> context<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> cancellationToken <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token class-name">JobKey</span> key <span class="token operator">=</span> context<span class="token punctuation">.</span>JobDetail<span class="token punctuation">.</span>Key<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token class-name">JobDataMap</span> dataMap <span class="token operator">=</span> context<span class="token punctuation">.</span>MergedJobDataMap<span class="token punctuation">;</span>  <span class="token comment">// Note the difference from the previous example</span></span>
<span class="line"></span>
<span class="line">  <span class="token class-name">IList<span class="token punctuation">&lt;</span>DateTimeOffset<span class="token punctuation">&gt;</span></span> state <span class="token operator">=</span> <span class="token punctuation">(</span>IList<span class="token operator">&lt;</span>DateTimeOffset<span class="token operator">&gt;</span><span class="token punctuation">)</span>dataMap<span class="token punctuation">[</span><span class="token string">&quot;myStateData&quot;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  state<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>DateTimeOffset<span class="token punctuation">.</span>UtcNow<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">await</span> Console<span class="token punctuation">.</span>Error<span class="token punctuation">.</span><span class="token function">WriteLineAsync</span><span class="token punctuation">(</span><span class="token string">&quot;Instance &quot;</span> <span class="token operator">+</span> key <span class="token operator">+</span> <span class="token string">&quot; of DumbJob says: &quot;</span> <span class="token operator">+</span> JobSays <span class="token operator">+</span> <span class="token string">&quot;, and val is: &quot;</span> <span class="token operator">+</span> FloatValue<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>You&#39;ll notice that the overall code of the class is longer, but the code in the <code>Execute()</code> method is cleaner. One could also argue that although the code is longer, that it actually took less coding, if the programmer&#39;s IDE was used to auto-generate the properties, rather than having to hand-code the individual calls to retrieve the values from the JobDataMap. The choice is yours.</p><h2 id="job-instances" tabindex="-1"><a class="header-anchor" href="#job-instances"><span>Job &quot;Instances&quot;</span></a></h2><p>Many users spend time being confused about what exactly constitutes a &quot;job instance&quot;. We&#39;ll try to clear that up here and in the section below about job state and concurrency.</p><p>You can create a single job class, and store many &#39;instance definitions&#39; of it within the scheduler by creating multiple instances of JobDetails</p><ul><li>each with its own set of properties and JobDataMap - and adding them all to the scheduler.</li></ul><p>For example, you can create a class that implements the <code>IJob</code> interface called &quot;SalesReportJob&quot;. The job might be coded to expect parameters sent to it (via the JobDataMap) to specify the name of the sales person that the sales report should be based on. They may then create multiple definitions (JobDetails) of the job, such as &quot;SalesReportForJoe&quot; and &quot;SalesReportForMike&quot; which have &quot;Joe&quot; and &quot;Mike&quot; specified in the corresponding JobDataMaps as input to the respective jobs.</p><p>When a trigger fires, the JobDetail (instance definition) it is associated to is loaded, and the job class it refers to is instantiated via the JobFactory configured on the Scheduler. Under <code>AddQuartz</code> that factory is <code>MicrosoftDependencyInjectionJobFactory</code>: it opens a service scope, resolves the job type from the container — constructor injection and all — and then sets any properties of the job whose names match keys in the merged JobDataMap. The scope is disposed when the fire ends, so a scoped <code>DbContext</code> belongs to the one execution that used it.</p><p>In &quot;Quartz speak&quot;, we refer to each stored JobDetail as a &quot;job definition&quot; or &quot;JobDetail instance&quot;, and we refer to a each executing job as a &quot;job instance&quot; or &quot;instance of a job definition&quot;. Usually if we just use the word &quot;job&quot; we are referring to a named definition, or JobDetail. When we are referring to the class implementing the job interface, we usually use the term &quot;job type&quot;.</p><h2 id="jobfactory" tabindex="-1"><a class="header-anchor" href="#jobfactory"><span>JobFactory</span></a></h2><p>When a trigger fires, the Job it is associated to is instantiated via the JobFactory configured on the Scheduler. <code>MicrosoftDependencyInjectionJobFactory</code> is the registered default, both under <code>AddQuartz</code> and under <code>QuartzSchedulerBuilder</code>, which builds a container of its own. <code>SimpleJobFactory</code> — which activates the type through its parameterless constructor and sets properties from the job data — is the base it is built on, and what a scheduler assembled without any container at all would use.</p><p>Write your own <code>IJobFactory</code> when a job has to be built some other way — resolved from a tenant&#39;s container, proxied, or handed something that only exists at fire time. A factory is set where the scheduler is configured — <code>q.UseJobFactory&lt;MyJobFactory&gt;()</code> or <code>q.UseJobFactory(new MyJobFactory())</code> — rather than assigned to the scheduler afterwards. To keep the container factory and only add to the scope it opens, use <code>q.ConfigureJobScope((scope, bundle, scheduler) =&gt; …)</code> instead of replacing the factory.</p><p>A factory returns a <code>JobScope</code>: the job, plus an optional opaque <code>State</code> object that Quartz hands straight back to <code>ReturnJob</code> when the job has finished. That is where anything the factory had to allocate in order to build the job belongs — a dependency injection scope, a connection, a tenant context — so the job itself stays the job.</p>`,20),a(`div`,d,[l[11]||=a(`p`,{class:`hint-container-title`},`Tips`,-1),a(`p`,null,[l[9]||=i(`There's `,-1),o(h,{to:`/documentation/quartz-4.x/packages/microsoft-di-integration.html`},{default:n(()=>[...l[8]||=[i(`built-in support for integrating with Microsoft Dependency Injection`,-1)]]),_:1}),l[10]||=i(` which in turn allows to use different IoC container implementations.`,-1)])]),l[15]||=e(`<h2 id="job-state-and-concurrency" tabindex="-1"><a class="header-anchor" href="#job-state-and-concurrency"><span>Job State and Concurrency</span></a></h2><p>Now, some additional notes about a job&#39;s state data (aka JobDataMap) and concurrency. There are a couple attributes that can be added to your Job class that affect Quartz&#39;s behaviour with respect to these aspects.</p><p><code>[DisallowConcurrentExecution]</code> is an attribute that can be added to the Job class that tells Quartz not to execute multiple instances of a given job definition (that refers to the given job class) concurrently. Notice the wording there, as it was chosen very carefully. In the example from the previous section, if &quot;SalesReportJob&quot; has this attribute, than only one instance of &quot;SalesReportForJoe&quot; can execute at a given time, but it can execute concurrently with an instance of &quot;SalesReportForMike&quot;. The constraint is based upon an instance definition (JobDetail), not on instances of the job class. However, it was decided (during the design of Quartz) to have the attribute carried on the class itself, because it does often make a difference to how the class is coded.</p><p><code>[PersistJobDataAfterExecution]</code> is an attribute that can be added to the Job class that tells Quartz to update the stored copy of the JobDetail&#39;s JobDataMap after the Execute() method completes (even if it throws a JobExecutionException), such that the next execution of the same job (JobDetail) receives the updated values rather than the originally stored values. Like the <code>[DisallowConcurrentExecution]</code> attribute, this applies to a job definition instance, not a job class instance, though it was decided to have the job class carry the attribute because it does often make a difference to how the class is coded (e.g. the &#39;statefulness&#39; will need to be explicitly &#39;understood&#39; by the code within the execute method).</p><p>If you use the <strong>PersistJobDataAfterExecution</strong> attribute, you should strongly consider also using the <code>[DisallowConcurrentExecution]</code> attribute, in order to avoid possible confusion (race conditions) of what data was left stored when two instances of the same job (JobDetail) executed concurrently.</p><h2 id="other-attributes-of-jobs" tabindex="-1"><a class="header-anchor" href="#other-attributes-of-jobs"><span>Other Attributes Of Jobs</span></a></h2><p>Here&#39;s a quick summary of the other properties which can be defined for a job instance via the JobDetail object:</p><ul><li><code>Durability</code> - if a job is non-durable, it is automatically deleted from the scheduler once there are no longer any active triggers associated with it. In other words, non-durable jobs have a life span bounded by the existence of its triggers.</li><li><code>RequestsRecovery</code> - if a job &quot;requests recovery&quot;, and it is executing during the time of a &#39;hard shutdown&#39; of the scheduler (i.e. the process it is running within crashes, or the machine is shut off), then it is re-executed when the scheduler is started again. In this case, the <code>JobExecutionContext.Recovering</code> property will return true.</li></ul><h2 id="a-jobdetail-of-your-own" tabindex="-1"><a class="header-anchor" href="#a-jobdetail-of-your-own"><span>A JobDetail of your own</span></a></h2><p><code>JobBuilder</code> builds Quartz&#39;s own <code>IJobDetail</code>, and that is what almost every application wants. If you need a job definition that carries something of yours alongside the ones above — a tenant, a correlation id, whatever the rest of your system keys on — you can implement <code>IJobDetail</code> yourself. Everything Quartz asks of a detail is declared on the interface:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TenantJobDetail</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">IJobDetail</span></span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token function">TenantJobDetail</span><span class="token punctuation">(</span><span class="token class-name">JobKey</span> key<span class="token punctuation">,</span> <span class="token class-name">JobType</span> jobType<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> tenant<span class="token punctuation">,</span> <span class="token class-name">JobDataMap</span> jobDataMap <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        Key <span class="token operator">=</span> key<span class="token punctuation">;</span></span>
<span class="line">        JobType <span class="token operator">=</span> jobType<span class="token punctuation">;</span></span>
<span class="line">        Tenant <span class="token operator">=</span> tenant<span class="token punctuation">;</span></span>
<span class="line">        JobDataMap <span class="token operator">=</span> jobDataMap <span class="token operator">??</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobDataMap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> Tenant <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">JobKey</span> Key <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> Description <span class="token operator">=&gt;</span> <span class="token interpolation-string"><span class="token string">$&quot;jobs for </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">Tenant</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">JobType</span> JobType <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">JobDataMap</span> JobDataMap <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">bool</span></span> Durable <span class="token operator">=&gt;</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">bool</span></span> PersistJobDataAfterExecution <span class="token operator">=&gt;</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">bool</span></span> ConcurrentExecutionDisallowed <span class="token operator">=&gt;</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">bool</span></span> RequestsRecovery <span class="token operator">=&gt;</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// How a job store re-stores the data a [PersistJobDataAfterExecution] job left behind: it asks the</span></span>
<span class="line">    <span class="token comment">// detail for a copy of itself rather than building one, which it could only do as Quartz&#39;s own type.</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">IJobDetail</span> <span class="token function">WithJobData</span><span class="token punctuation">(</span><span class="token class-name">JobDataMap</span> jobDataMap<span class="token punctuation">)</span></span>
<span class="line">        <span class="token operator">=&gt;</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TenantJobDetail</span><span class="token punctuation">(</span>Key<span class="token punctuation">,</span> JobType<span class="token punctuation">,</span> Tenant<span class="token punctuation">,</span> jobDataMap<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">IJobDetail</span> <span class="token function">Clone</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token operator">=&gt;</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TenantJobDetail</span><span class="token punctuation">(</span>Key<span class="token punctuation">,</span> JobType<span class="token punctuation">,</span> Tenant<span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobDataMap</span><span class="token punctuation">(</span>JobDataMap<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">How far it travels</p><p>A detail of your own round-trips through <code>RAMJobStore</code>, which holds the instances it is given and hands back clones of them. It does not survive a store or a transport that keeps a detail as data: the ADO.NET job store writes the columns of <code>QRTZ_JOB_DETAILS</code> and rebuilds every detail it reads through <code>JobBuilder</code>, so what comes back is Quartz&#39;s own implementation, and the HTTP client rebuilds one the same way from its wire payload. Anything your type carries beyond the members above is gone by then — put it in the <code>JobDataMap</code> if it has to come back.</p></div><p><code>detail.GetJobBuilder()</code> is an extension method over the interface, so it works on a detail of your own too. It describes the detail rather than preserving it: what it builds is Quartz&#39;s <code>IJobDetail</code>. Use <code>WithJobData</code> to vary the data of a detail of your own, and <code>Clone()</code> to copy one.</p><h2 id="jobexecutionexception" tabindex="-1"><a class="header-anchor" href="#jobexecutionexception"><span>JobExecutionException</span></a></h2><p>Finally, we need to inform you of a few details of the <code>IJob.Execute(..)</code> method. The only type of exception that you should throw from the execute method is the JobExecutionException. Because of this, you should generally wrap the entire contents of the execute method with a &#39;try-catch&#39; block. The exception&#39;s directives to the scheduler are init-only properties, set with an object initializer:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> ex<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// ask the scheduler to run this fire again with the same context</span></span>
<span class="line">    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobExecutionException</span><span class="token punctuation">(</span>ex<span class="token punctuation">)</span> <span class="token punctuation">{</span> RefireImmediately <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Besides <code>RefireImmediately</code> there are <code>UnscheduleFiringTrigger</code> and <code>UnscheduleAllTriggers</code>, which stop the trigger that fired the job — or every trigger of the job — from firing again. When <code>RefireImmediately</code> is set, the unschedule flags are ignored.</p>`,17)])}var p=s(u,[[`render`,f]]);export{l as _pageData,p as default};